SOLUTIONS = {64: {'q_id': 114, 'filename': 'day64_q1.c', 'topic': 'Length of longest substring without repeating characters', 'source': '/**\n * Day 64 - Question 114\n * \n * Write a program to take a string s as input. The task is to find the length of the longest substring without repeating characters. Print the length as output.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: s = "abcabcbb"\n *   Output: 3\n *   Explanation: The answer is "abc", with the length of 3. Note that "bca" and "cab" are also correct answers.\n * Test Case 2:\n *   Input: s = "bbbbb"\n *   Output: 1\n *   Explanation: The answer is "b", with the length of 1.\n * Test Case 3:\n *   Input: s = "pwwkew"\n *   Output: 3\n *   Explanation: The answer is "wke", with the length of 3. Notice that the answer must be a substring, "pwke" is a subsequence and not a substring.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nint lengthOfLongestSubstring(const char *s) {\n    int lastPos[256];\n    for (int i = 0; i < 256; i++) lastPos[i] = -1;\n    \n    int maxLen = 0, start = 0;\n    int n = strlen(s);\n    \n    for (int i = 0; i < n; i++) {\n        unsigned char ch = (unsigned char)s[i];\n        if (lastPos[ch] >= start) {\n            start = lastPos[ch] + 1;\n        }\n        lastPos[ch] = i;\n        int curLen = i - start + 1;\n        if (curLen > maxLen) {\n            maxLen = curLen;\n        }\n    }\n    return maxLen;\n}\n\nint main() {\n    char s[1000];\n    if (fgets(s, sizeof(s), stdin)) {\n        s[strcspn(s, "\\r\\n")] = \'\\0\';\n        char *p = s;\n        char *q1 = strchr(p, \'"\');\n        if (q1) {\n            p = q1 + 1;\n            char *q2 = strrchr(p, \'"\');\n            if (q2) *q2 = \'\\0\';\n        }\n        printf("%d\\n", lengthOfLongestSubstring(p));\n    }\n    return 0;\n}\n'}, 65: {'q_id': 115, 'filename': 'day65_q1.c', 'topic': 'Valid Anagram check', 'source': '/**\n * Day 65 - Question 115\n * \n * Write a program to take two strings s and t as inputs (assume all characters are lowercase). The task is to determine if s and t are valid anagrams, meaning they contain the same characters with the same frequencies. Print "Anagram" if they are, otherwise "Not Anagram".\n * \n * Test Cases:\n * Test Case 1:\n *   Input: s = "anagram", t = "nagaram"\n *   Output: Anagram\n *   Explanation: The strings contain the same characters with the same frequencies.\n * Test Case 2:\n *   Input: s = "rat", t = "car"\n *   Output: Not Anagram\n *   Explanation: The strings do not contain the same characters.\n */\n\n#include <stdio.h>\n#include <string.h>\n#include <stdbool.h>\n\nbool isAnagram(const char *s, const char *t) {\n    if (strlen(s) != strlen(t)) return false;\n    int count[256] = {0};\n    for (int i = 0; s[i] != \'\\0\'; i++) {\n        count[(unsigned char)s[i]]++;\n        count[(unsigned char)t[i]]--;\n    }\n    for (int i = 0; i < 256; i++) {\n        if (count[i] != 0) return false;\n    }\n    return true;\n}\n\nint main() {\n    char s[500], t[500];\n    if (scanf("%499s %499s", s, t) == 2) {\n        if (isAnagram(s, t)) {\n            printf("Anagram\\n");\n        } else {\n            printf("Not Anagram\\n");\n        }\n    }\n    return 0;\n}\n'}, 66: {'q_id': 116, 'filename': 'day66_q1.c', 'topic': 'Two Sum (indices of elements adding to target)', 'source': '/**\n * Day 66 - Question 116\n * \n * Write a program to take an integer array nums which contains only positive integers, and an integer target as inputs. The goal is to find two distinct indices i and j in the array such that nums[i] + nums[j] equals the target. Assume exactly one solution exists and return the indices in any order. Print the two indices separated by a space as output. If no solution exists, print "-1 -1".\n * \n * Test Cases:\n * Test Case 1:\n *   Input: nums = [2,7,11,15], target = 9\n *   Output: 0 1\n *   Explanation: Because nums[0] + nums[1] == 9, we return [0, 1].\n * Test Case 2:\n *   Input: nums = [3,2,4], target = 6\n *   Output: 1 2\n * Test Case 3:\n *   Input: nums = [3,3], target = 6\n *   Output: 0 1\n */\n\n#include <stdio.h>\n\nint main() {\n    int n, target;\n    if (scanf("%d", &n) != 1 || n <= 0) return 0;\n    int nums[1000];\n    for (int i = 0; i < n; i++) {\n        scanf("%d", &nums[i]);\n    }\n    scanf("%d", &target);\n    \n    int found = 0;\n    for (int i = 0; i < n; i++) {\n        for (int j = i + 1; j < n; j++) {\n            if (nums[i] + nums[j] == target) {\n                printf("%d %d\\n", i, j);\n                found = 1;\n                break;\n            }\n        }\n        if (found) break;\n    }\n    if (!found) {\n        printf("-1 -1\\n");\n    }\n    return 0;\n}\n'}, 67: {'q_id': 117, 'filename': 'day67_q1.c', 'topic': 'Merge two sorted arrays', 'source': '/**\n * Day 67 - Question 117\n * \n * Write a program to take two sorted arrays of size m and n as input. Merge both the arrays such that the merged array is also sorted. Print the merged array.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: nums1 = [2,7,11,15] nums2 = [4,8,10]\n *   Output: 2 4 7 8 10 11 15\n * Test Case 2:\n *   Input: nums1 = [1,2,7] nums2 = [9,10,17]\n *   Output: 1 2 7 9 10 17\n * Test Case 3:\n *   Input: nums1 = [-10,-2,7] nums2 = [-3, -1, 7]\n *   Output: -10 -3 -2 -1 7 7\n */\n\n#include <stdio.h>\n\nvoid mergeSorted(int a[], int m, int b[], int n, int res[]) {\n    int i = 0, j = 0, k = 0;\n    while (i < m && j < n) {\n        if (a[i] <= b[j]) {\n            res[k++] = a[i++];\n        } else {\n            res[k++] = b[j++];\n        }\n    }\n    while (i < m) res[k++] = a[i++];\n    while (j < n) res[k++] = b[j++];\n}\n\nint main() {\n    int m, n;\n    if (scanf("%d", &m) != 1) return 0;\n    int a[1000];\n    for (int i = 0; i < m; i++) scanf("%d", &a[i]);\n    if (scanf("%d", &n) != 1) return 0;\n    int b[1000];\n    for (int i = 0; i < n; i++) scanf("%d", &b[i]);\n    \n    int res[2000];\n    mergeSorted(a, m, b, n, res);\n    for (int i = 0; i < m + n; i++) {\n        printf("%d%c", res[i], (i == m + n - 1) ? \'\\n\' : \' \');\n    }\n    return 0;\n}\n'}, 68: {'q_id': 118, 'filename': 'day68_q1.c', 'topic': 'Find missing number from 0 to n', 'source': '/**\n * Day 68 - Question 118\n * \n * Write a program to take an input array of size n. The array should contain all the integers between 0 to n except for one. Print that missing number\n * \n * Test Cases:\n * Test Case 1:\n *   Input: nums1 = [0,3,2,4]\n *   Output: 1\n * Test Case 2:\n *   Input: nums1 = [1,2,3]\n *   Output: 0\n * Test Case 3:\n *   Input: nums1 = [0,4,3,1,5]\n *   Output: 2\n */\n\n#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) != 1) return 0;\n    long long totalExpected = (long long)n * (n + 1) / 2;\n    long long actualSum = 0;\n    for (int i = 0; i < n; i++) {\n        int val;\n        scanf("%d", &val);\n        actualSum += val;\n    }\n    printf("%lld\\n", totalExpected - actualSum);\n    return 0;\n}\n'}, 69: {'q_id': 119, 'filename': 'day69_q1.c', 'topic': 'Find repeated element in single iteration', 'source': '/**\n * Day 69 - Question 119\n * \n * Write a program to take an integer array as input. Only one element will be repeated. Print the repeated element. Try to find the result in one single iteration.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: nums1 = [1,3,3,4]\n *   Output: 3\n * Test Case 2:\n *   Input: nums1 = [1,2,2]\n *   Output: 2\n * Test Case 3:\n *   Input: nums1 = [0,4,1,1,5]\n *   Output: 1\n */\n\n#include <stdio.h>\n\n#define MAX_VAL 1000005\nstatic int visited[MAX_VAL];\n\nint main() {\n    int n;\n    if (scanf("%d", &n) != 1) return 0;\n    int repeated = -1;\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf("%d", &x);\n        if (x >= 0 && x < MAX_VAL && visited[x]) {\n            if (repeated == -1) repeated = x;\n        } else if (x >= 0 && x < MAX_VAL) {\n            visited[x] = 1;\n        }\n    }\n    printf("%d\\n", repeated);\n    return 0;\n}\n'}, 70: {'q_id': 120, 'filename': 'day70_q1.c', 'topic': 'Convert string to sentence case / title case', 'source': '/**\n * Day 70 - Question 120\n * \n * Write a program to take a string input. Change it to sentence case.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: str = I am trying to build logic.\n *   Output: I Am Trying To Build Logic\n * Test Case 2:\n *   Input: str = The classes are supposed to start early.\n *   Output: The Classes Are Supposed To Start Early.\n * Test Case 3:\n *   Input: str = We are going to look at 26 different test cases.\n *   Output: We Are Going To Look At 26 Different Test Cases.\n */\n\n#include <stdio.h>\n#include <string.h>\n#include <ctype.h>\n\nint main() {\n    char str[1000];\n    if (fgets(str, sizeof(str), stdin)) {\n        str[strcspn(str, "\\r\\n")] = \'\\0\';\n        int newWord = 1;\n        for (int i = 0; str[i] != \'\\0\'; i++) {\n            if (isspace((unsigned char)str[i])) {\n                newWord = 1;\n            } else if (newWord) {\n                str[i] = toupper((unsigned char)str[i]);\n                newWord = 0;\n            } else {\n                str[i] = tolower((unsigned char)str[i]);\n            }\n        }\n        printf("%s\\n", str);\n    }\n    return 0;\n}\n'}, 71: {'q_id': 121, 'filename': 'day71_q1.c', 'topic': 'Create info.txt and write user data using fprintf', 'source': '/**\n * Day 71 - Question 121\n * \n * Write a C program that creates a text file named info.txt in write mode. The program should take the user’s name and age as input, and write them to the file using fprintf(). After writing, display a message confirming that the data was successfully saved.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Name: Rahul, Age: 23\n *   Output: File created successfully! Data written to info.txt\n *   Explanation: Expected File Content (info.txt): Name: Rahul Age: 23\n */\n\n#include <stdio.h>\n\nint main() {\n    char name[100];\n    int age;\n    printf("Enter Name and Age: ");\n    if (scanf("%99s %d", name, &age) == 2) {\n        FILE *fp = fopen("info.txt", "w");\n        if (fp == NULL) {\n            printf("Error opening file!\\n");\n            return 1;\n        }\n        fprintf(fp, "Name: %s\\nAge: %d\\n", name, age);\n        fclose(fp);\n        printf("File created successfully! Data written to info.txt\\n");\n    }\n    return 0;\n}\n'}, 72: {'q_id': 122, 'filename': 'day72_q1.c', 'topic': 'Read existing file info.txt using fgets', 'source': '/**\n * Day 72 - Question 122\n * \n * Write a C program that opens an existing file (e.g., info.txt) and reads its contents using fgets(). The program should print all the lines to the console until EOF (end of file) is reached.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: File: info.txt (Content: Name: Rahul\\nAge: 23)\n *   Output: Name: Rahul\nAge: 23\n *   Explanation: The program reads each line from info.txt using fgets() and prints it until EOF.\n */\n\n#include <stdio.h>\n\nint main() {\n    FILE *fp = fopen("info.txt", "r");\n    if (fp == NULL) {\n        printf("Error: Could not open info.txt!\\n");\n        return 1;\n    }\n    char buffer[256];\n    while (fgets(buffer, sizeof(buffer), fp) != NULL) {\n        printf("%s", buffer);\n    }\n    fclose(fp);\n    return 0;\n}\n'}, 73: {'q_id': 123, 'filename': 'day73_q1.c', 'topic': 'Count characters, words, and lines in a text file', 'source': '/**\n * Day 73 - Question 123\n * \n * Read a text file and count the total number of characters, words, and lines. A word is defined as a sequence of non-space characters separated by spaces or newlines.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: File: sample.txt (Content: Hello world\\nThis is C programming)\n *   Output: Characters: 31\nWords: 5\nLines: 2\n *   Explanation: The file has 31 characters including spaces and newlines, 5 words, and 2 lines.\n */\n\n#include <stdio.h>\n#include <ctype.h>\n\nint main() {\n    char filename[100];\n    if (scanf("%99s", filename) != 1) return 0;\n    FILE *fp = fopen(filename, "r");\n    if (fp == NULL) {\n        printf("Error: Could not open file %s\\n", filename);\n        return 1;\n    }\n    int chars = 0, words = 0, lines = 0;\n    int inWord = 0;\n    int ch, lastCh = \'\\n\';\n    while ((ch = fgetc(fp)) != EOF) {\n        chars++;\n        if (ch == \'\\n\') lines++;\n        if (isspace(ch)) {\n            inWord = 0;\n        } else if (!inWord) {\n            inWord = 1;\n            words++;\n        }\n        lastCh = ch;\n    }\n    if (chars > 0 && lastCh != \'\\n\') lines++;\n    fclose(fp);\n    printf("Characters: %d\\nWords: %d\\nLines: %d\\n", chars, words, lines);\n    return 0;\n}\n'}, 74: {'q_id': 124, 'filename': 'day74_q1.c', 'topic': 'Copy source file to destination using fgetc and fputc', 'source': '/**\n * Day 74 - Question 124\n * \n * Take two filenames from the user – a source file and a destination file. Copy all the content from the source file to the destination file using fgetc() and fputc().\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Source File: source.txt (Content: Learning C File Handling)\n *   Output: File copied successfully to destination.txt\n *   Explanation: Expected File (destination.txt): Learning C File Handling\n */\n\n#include <stdio.h>\n\nint main() {\n    char src[100], dst[100];\n    if (scanf("%99s %99s", src, dst) != 2) return 0;\n    FILE *fsrc = fopen(src, "r");\n    if (fsrc == NULL) {\n        printf("Error: Source file does not exist!\\n");\n        return 1;\n    }\n    FILE *fdst = fopen(dst, "w");\n    if (fdst == NULL) {\n        printf("Error: Destination file could not be created!\\n");\n        fclose(fsrc);\n        return 1;\n    }\n    int ch;\n    while ((ch = fgetc(fsrc)) != EOF) {\n        fputc(ch, fdst);\n    }\n    fclose(fsrc);\n    fclose(fdst);\n    printf("File copied successfully to %s\\n", dst);\n    return 0;\n}\n'}, 75: {'q_id': 125, 'filename': 'day75_q1.c', 'topic': 'Append text to existing file without overwriting', 'source': '/**\n * Day 75 - Question 125\n * \n * Open an existing file in append mode and allow the user to enter a new line of text. Append the text at the end without overwriting existing content.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Existing File: data.txt (Content before execution: Hello world)\nUser Input: This is appended text.\n *   Output: File updated successfully with appended text.\n *   Explanation: Output File (data.txt after execution): Hello world\\nThis is appended text.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char filename[100];\n    char text[500];\n    if (scanf("%99s", filename) != 1) return 0;\n    getchar();\n    if (fgets(text, sizeof(text), stdin)) {\n        text[strcspn(text, "\\r\\n")] = \'\\0\';\n        FILE *fp = fopen(filename, "a");\n        if (fp == NULL) {\n            printf("Error opening file!\\n");\n            return 1;\n        }\n        fprintf(fp, "\\n%s", text);\n        fclose(fp);\n        printf("File updated successfully with appended text.\\n");\n    }\n    return 0;\n}\n'}, 76: {'q_id': 126, 'filename': 'day76_q1.c', 'topic': 'Check file existence and read content', 'source': '/**\n * Day 76 - Question 126\n * \n * Ask the user for a filename. Check if it exists by trying to open it in read mode. If the file pointer is NULL, print an error message; otherwise, read and display its content.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Filename: sample.txt (File Exists: Yes)\n *   Output: File opened successfully.\n(Displays file content)\n *   Explanation: The program opens the existing file and prints its content using fgets().\n * Test Case 2:\n *   Input: Filename: nofile.txt (File Exists: No)\n *   Output: Error: File does not exist!\n *   Explanation: Since fopen() returns NULL, an error message is displayed instead of reading.\n */\n\n#include <stdio.h>\n\nint main() {\n    char filename[100];\n    if (scanf("%99s", filename) != 1) return 0;\n    FILE *fp = fopen(filename, "r");\n    if (fp == NULL) {\n        printf("Error: File does not exist!\\n");\n    } else {\n        printf("File opened successfully.\\n");\n        char buffer[256];\n        while (fgets(buffer, sizeof(buffer), fp) != NULL) {\n            printf("%s", buffer);\n        }\n        fclose(fp);\n    }\n    return 0;\n}\n'}, 77: {'q_id': 127, 'filename': 'day77_q1.c', 'topic': 'Convert input.txt lowercase to uppercase and write to output.txt', 'source': '/**\n * Day 77 - Question 127\n * \n * Write a program that reads text from input.txt, converts all lowercase letters to uppercase, and writes the result to output.txt.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Input File (input.txt): Hello World\\nC programming\n *   Output: Output File (output.txt): HELLO WORLD\\nC PROGRAMMING\n *   Explanation: All lowercase letters in input.txt are converted to uppercase using character manipulation before writing to output.txt.\n */\n\n#include <stdio.h>\n#include <ctype.h>\n\nint main() {\n    FILE *in = fopen("input.txt", "r");\n    if (in == NULL) {\n        printf("Error: Could not open input.txt\\n");\n        return 1;\n    }\n    FILE *out = fopen("output.txt", "w");\n    if (out == NULL) {\n        printf("Error: Could not create output.txt\\n");\n        fclose(in);\n        return 1;\n    }\n    int ch;\n    while ((ch = fgetc(in)) != EOF) {\n        fputc(toupper((unsigned char)ch), out);\n    }\n    fclose(in);\n    fclose(out);\n    printf("Successfully converted and written to output.txt\\n");\n    return 0;\n}\n'}, 78: {'q_id': 128, 'filename': 'day78_q1.c', 'topic': 'Count vowels and consonants in text file', 'source': '/**\n * Day 78 - Question 128\n * \n * Read a text file and count how many vowels and consonants are in the file. Ignore digits and special characters.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: File: text.txt (Content: Welcome to C language)\n *   Output: Vowels: 8\nConsonants: 10\n *   Explanation: The program iterates through each character, counts vowels (A, E, I, O, U) and consonants, ignoring other symbols.\n */\n\n#include <stdio.h>\n#include <ctype.h>\n\nint main() {\n    char filename[100];\n    if (scanf("%99s", filename) != 1) return 0;\n    FILE *fp = fopen(filename, "r");\n    if (fp == NULL) {\n        printf("Error: Could not open file %s\\n", filename);\n        return 1;\n    }\n    int vowels = 0, consonants = 0;\n    int ch;\n    while ((ch = fgetc(fp)) != EOF) {\n        if (isalpha(ch)) {\n            char lower = tolower((unsigned char)ch);\n            if (lower == \'a\' || lower == \'e\' || lower == \'i\' || lower == \'o\' || lower == \'u\') {\n                vowels++;\n            } else {\n                consonants++;\n            }\n        }\n    }\n    fclose(fp);\n    printf("Vowels: %d\\nConsonants: %d\\n", vowels, consonants);\n    return 0;\n}\n'}, 79: {'q_id': 129, 'filename': 'day79_q1.c', 'topic': 'Sum and average of integers in numbers.txt', 'source': '/**\n * Day 79 - Question 129\n * \n * A file numbers.txt contains a list of integers separated by spaces. Read all integers, compute their sum and average, and print both.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: File: numbers.txt (Content: 10 20 30 40 50)\n *   Output: Sum = 150\nAverage = 30.00\n *   Explanation: The program reads integers from the file, computes their total sum (150), and calculates the average (30.00).\n */\n\n#include <stdio.h>\n\nint main() {\n    FILE *fp = fopen("numbers.txt", "r");\n    if (fp == NULL) {\n        printf("Error: Could not open numbers.txt\\n");\n        return 1;\n    }\n    int num, count = 0;\n    long long sum = 0;\n    while (fscanf(fp, "%d", &num) == 1) {\n        sum += num;\n        count++;\n    }\n    fclose(fp);\n    if (count > 0) {\n        printf("Sum = %lld\\nAverage = %.2f\\n", sum, (double)sum / count);\n    } else {\n        printf("Sum = 0\\nAverage = 0.00\\n");\n    }\n    return 0;\n}\n'}, 80: {'q_id': 130, 'filename': 'day80_q1.c', 'topic': 'Store and read student records using fprintf and fscanf', 'source': '/**\n * Day 80 - Question 130\n * \n * Store multiple student records (name, roll number, marks) into a file using fprintf(). Then read them using fscanf() and display each record.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Student 1 → Name: Asha, Roll: 101, Marks: 85; Student 2 → Name: Ravi, Roll: 102, Marks: 92\n *   Output: Name: Asha | Roll: 101 | Marks: 85\nName: Ravi | Roll: 102 | Marks: 92\n *   Explanation: Expected File Content (students.txt): Asha 101 85\\nRavi 102 92\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nint main() {\n    int n;\n    printf("Enter number of students: ");\n    if (scanf("%d", &n) != 1 || n <= 0) return 0;\n    struct Student s[50];\n    for (int i = 0; i < n; i++) {\n        scanf("%49s %d %d", s[i].name, &s[i].roll, &s[i].marks);\n    }\n    FILE *fp = fopen("students.txt", "w");\n    if (fp == NULL) return 1;\n    for (int i = 0; i < n; i++) {\n        fprintf(fp, "%s %d %d\\n", s[i].name, s[i].roll, s[i].marks);\n    }\n    fclose(fp);\n\n    fp = fopen("students.txt", "r");\n    if (fp == NULL) return 1;\n    struct Student readS;\n    while (fscanf(fp, "%49s %d %d", readS.name, &readS.roll, &readS.marks) == 3) {\n        printf("Name: %s | Roll: %d | Marks: %d\\n", readS.name, readS.roll, readS.marks);\n    }\n    fclose(fp);\n    return 0;\n}\n'}, 81: {'q_id': 131, 'filename': 'day81_q1.c', 'topic': 'Enumeration for days (SUNDAY to SATURDAY) and integer values', 'source': '/**\n * Day 81 - Question 131\n * \n * Create an enumeration for days (SUNDAY to SATURDAY) and print each day with its integer value.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: No input\n *   Output: SUNDAY = 0\nMONDAY = 1\nTUESDAY = 2\nWEDNESDAY = 3\nTHURSDAY = 4\nFRIDAY = 5\nSATURDAY = 6\n *   Explanation: Each day in the enum is automatically assigned an integer starting from 0.\n */\n\n#include <stdio.h>\n\nenum Day {\n    SUNDAY,\n    MONDAY,\n    TUESDAY,\n    WEDNESDAY,\n    THURSDAY,\n    FRIDAY,\n    SATURDAY\n};\n\nint main() {\n    const char *names[] = {\n        "SUNDAY", "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY"\n    };\n    for (int d = SUNDAY; d <= SATURDAY; d++) {\n        printf("%s = %d\\n", names[d], d);\n    }\n    return 0;\n}\n'}, 82: {'q_id': 132, 'filename': 'day82_q1.c', 'topic': 'Enum for traffic lights (RED, YELLOW, GREEN)', 'source': '/**\n * Day 82 - Question 132\n * \n * Define an enum for traffic lights (RED, YELLOW, GREEN) and print \'Stop\', \'Wait\', or \'Go\' based on its value.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: GREEN\n *   Output: Go\n *   Explanation: When the enum value is GREEN, the program prints \'Go\'.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum TrafficLight { RED, YELLOW, GREEN };\n\nint main() {\n    char input[20];\n    if (scanf("%19s", input) == 1) {\n        enum TrafficLight light;\n        if (strcmp(input, "RED") == 0) light = RED;\n        else if (strcmp(input, "YELLOW") == 0) light = YELLOW;\n        else light = GREEN;\n\n        switch (light) {\n            case RED:    printf("Stop\\n"); break;\n            case YELLOW: printf("Wait\\n"); break;\n            case GREEN:  printf("Go\\n"); break;\n        }\n    }\n    return 0;\n}\n'}, 83: {'q_id': 133, 'filename': 'day83_q1.c', 'topic': 'Enum for months and days count', 'source': '/**\n * Day 83 - Question 133\n * \n * Create an enum for months and print how many days each month has.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: FEB\n *   Output: 28 or 29 days\n *   Explanation: February has 28 days in a normal year and 29 in a leap year.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum Month {\n    JAN = 1, FEB, MAR, APR, MAY, JUN,\n    JUL, AUG, SEP, OCT, NOV, DEC\n};\n\nint main() {\n    char mName[10];\n    if (scanf("%9s", mName) == 1) {\n        if (strcmp(mName, "FEB") == 0) {\n            printf("28 or 29 days\\n");\n        } else if (strcmp(mName, "APR") == 0 || strcmp(mName, "JUN") == 0 ||\n                   strcmp(mName, "SEP") == 0 || strcmp(mName, "NOV") == 0) {\n            printf("30 days\\n");\n        } else {\n            printf("31 days\\n");\n        }\n    }\n    return 0;\n}\n'}, 84: {'q_id': 134, 'filename': 'day84_q1.c', 'topic': 'Enum SUCCESS, FAILURE, TIMEOUT status messages', 'source': '/**\n * Day 84 - Question 134\n * \n * Define an enum with SUCCESS, FAILURE, and TIMEOUT, and print messages accordingly.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: FAILURE\n *   Output: Operation failed\n *   Explanation: FAILURE corresponds to a failed operation message.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum Status { SUCCESS, FAILURE, TIMEOUT };\n\nint main() {\n    char input[20];\n    if (scanf("%19s", input) == 1) {\n        enum Status s;\n        if (strcmp(input, "SUCCESS") == 0) s = SUCCESS;\n        else if (strcmp(input, "FAILURE") == 0) s = FAILURE;\n        else s = TIMEOUT;\n\n        switch (s) {\n            case SUCCESS: printf("Operation successful\\n"); break;\n            case FAILURE: printf("Operation failed\\n"); break;\n            case TIMEOUT: printf("Operation timed out\\n"); break;\n        }\n    }\n    return 0;\n}\n'}, 85: {'q_id': 135, 'filename': 'day85_q1.c', 'topic': 'Explicit enum values starting from 10', 'source': '/**\n * Day 85 - Question 135\n * \n * Assign explicit values starting from 10 and print them.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: No input\n *   Output: A=10\nB=11\nC=12\n *   Explanation: Enum values can be explicitly assigned; subsequent values auto-increment.\n */\n\n#include <stdio.h>\n\nenum CustomEnum {\n    A = 10,\n    B,\n    C\n};\n\nint main() {\n    printf("A=%d\\n", A);\n    printf("B=%d\\n", B);\n    printf("C=%d\\n", C);\n    return 0;\n}\n'}, 86: {'q_id': 136, 'filename': 'day86_q1.c', 'topic': 'Menu choices (ADD, SUBTRACT, MULTIPLY) using enum & switch', 'source': '/**\n * Day 86 - Question 136\n * \n * Use enum to represent menu choices (ADD, SUBTRACT, MULTIPLY) and perform operations using switch.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: ADD 10 20\n *   Output: 30\n *   Explanation: The enum ADD triggers addition of 10 and 20.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum Operation { ADD = 1, SUBTRACT, MULTIPLY };\n\nint main() {\n    char op[20];\n    int a, b;\n    if (scanf("%19s %d %d", op, &a, &b) == 3) {\n        enum Operation choice;\n        if (strcmp(op, "ADD") == 0) choice = ADD;\n        else if (strcmp(op, "SUBTRACT") == 0) choice = SUBTRACT;\n        else choice = MULTIPLY;\n\n        switch (choice) {\n            case ADD:      printf("%d\\n", a + b); break;\n            case SUBTRACT: printf("%d\\n", a - b); break;\n            case MULTIPLY: printf("%d\\n", a * b); break;\n        }\n    }\n    return 0;\n}\n'}, 87: {'q_id': 137, 'filename': 'day87_q1.c', 'topic': 'Enum for user roles (ADMIN, USER, GUEST)', 'source': '/**\n * Day 87 - Question 137\n * \n * Create an enum for user roles (ADMIN, USER, GUEST) and display messages based on role.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: GUEST\n *   Output: Welcome Guest!\n *   Explanation: Enum value determines which message is displayed.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum Role { ADMIN, USER, GUEST };\n\nint main() {\n    char roleStr[20];\n    if (scanf("%19s", roleStr) == 1) {\n        enum Role r;\n        if (strcmp(roleStr, "ADMIN") == 0) r = ADMIN;\n        else if (strcmp(roleStr, "USER") == 0) r = USER;\n        else r = GUEST;\n\n        switch (r) {\n            case ADMIN: printf("Welcome Admin!\\n"); break;\n            case USER:  printf("Welcome User!\\n"); break;\n            case GUEST: printf("Welcome Guest!\\n"); break;\n        }\n    }\n    return 0;\n}\n'}, 88: {'q_id': 138, 'filename': 'day88_q1.c', 'topic': 'Print all enum names and integer values using a loop', 'source': '/**\n * Day 88 - Question 138\n * \n * Print all enum names and integer values using a loop.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: No input\n *   Output: RED=0\nYELLOW=1\nGREEN=2\n *   Explanation: Iterating through enum values prints each constant with its assigned integer.\n */\n\n#include <stdio.h>\n\nenum Color { RED, YELLOW, GREEN, COLOR_COUNT };\n\nint main() {\n    const char *names[] = {"RED", "YELLOW", "GREEN"};\n    for (int i = 0; i < COLOR_COUNT; i++) {\n        printf("%s=%d\\n", names[i], i);\n    }\n    return 0;\n}\n'}, 89: {'q_id': 139, 'filename': 'day89_q1.c', 'topic': 'Show that enums store integers by printing assigned values', 'source': '/**\n * Day 89 - Question 139\n * \n * Show that enums store integers by printing assigned values.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: No input\n *   Output: SUCCESS=0, FAILURE=1, TIMEOUT=2\n *   Explanation: Enum constants are internally stored as integer values starting from 0.\n */\n\n#include <stdio.h>\n\nenum Code { SUCCESS = 0, FAILURE = 1, TIMEOUT = 2 };\n\nint main() {\n    printf("SUCCESS=%d, FAILURE=%d, TIMEOUT=%d\\n", SUCCESS, FAILURE, TIMEOUT);\n    return 0;\n}\n'}, 90: {'q_id': 140, 'filename': 'day90_q1.c', 'topic': 'Struct with enum Gender', 'source': '/**\n * Day 90 - Question 140\n * \n * Define a struct with enum Gender and print person\'s gender.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Gender=MALE\n *   Output: Male\n *   Explanation: The enum inside the struct allows representing gender as a named constant.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nenum Gender { MALE, FEMALE, OTHER };\n\nstruct Person {\n    char name[50];\n    enum Gender gender;\n};\n\nint main() {\n    char gStr[20];\n    if (scanf("%19s", gStr) == 1) {\n        struct Person p;\n        if (strstr(gStr, "MALE") || strstr(gStr, "Male")) {\n            p.gender = MALE;\n        } else if (strstr(gStr, "FEMALE") || strstr(gStr, "Female")) {\n            p.gender = FEMALE;\n        } else {\n            p.gender = OTHER;\n        }\n\n        switch (p.gender) {\n            case MALE:   printf("Male\\n"); break;\n            case FEMALE: printf("Female\\n"); break;\n            case OTHER:  printf("Other\\n"); break;\n        }\n    }\n    return 0;\n}\n'}, 91: {'q_id': 141, 'filename': 'day91_q1.c', 'topic': 'Structure Student (name, roll_no, marks)', 'source': '/**\n * Day 91 - Question 141\n * \n * Define a structure Student with name, roll_no, and marks, then read and print one student\'s data.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Name: Asha\nRoll: 101\nMarks: 90\n *   Output: Name: Asha | Roll: 101 | Marks: 90\n *   Explanation: The program stores and displays one student\'s details using structure members.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll_no;\n    int marks;\n};\n\nint main() {\n    struct Student s;\n    if (scanf("%49s %d %d", s.name, &s.roll_no, &s.marks) == 3) {\n        printf("Name: %s | Roll: %d | Marks: %d\\n", s.name, s.roll_no, s.marks);\n    }\n    return 0;\n}\n'}, 92: {'q_id': 142, 'filename': 'day92_q1.c', 'topic': 'Store details of 5 students in array of structures', 'source': '/**\n * Day 92 - Question 142\n * \n * Store details of 5 students in an array of structures and print all.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Details of 5 students (Name, Roll, Marks)\n *   Output: Tabular list of all 5 students with their details\n *   Explanation: The array of structures stores multiple student records and displays them in a table.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nint main() {\n    struct Student students[5];\n    for (int i = 0; i < 5; i++) {\n        if (scanf("%49s %d %d", students[i].name, &students[i].roll, &students[i].marks) != 3) {\n            break;\n        }\n    }\n    printf("%-15s %-10s %-10s\\n", "Name", "Roll", "Marks");\n    printf("-----------------------------------\\n");\n    for (int i = 0; i < 5; i++) {\n        printf("%-15s %-10d %-10d\\n", students[i].name, students[i].roll, students[i].marks);\n    }\n    return 0;\n}\n'}, 93: {'q_id': 143, 'filename': 'day93_q1.c', 'topic': 'Find and print student with highest marks', 'source': '/**\n * Day 93 - Question 143\n * \n * Find and print the student with the highest marks.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: 3 students: Ravi 101 95, Sita 102 85, Aman 103 88\n *   Output: Topper: Ravi (Marks: 95)\n *   Explanation: Program compares marks of all students and prints the one with the highest.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nint main() {\n    int n;\n    if (scanf("%d", &n) != 1 || n <= 0) return 0;\n    struct Student students[100];\n    int maxIdx = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%49s %d %d", students[i].name, &students[i].roll, &students[i].marks);\n        if (students[i].marks > students[maxIdx].marks) {\n            maxIdx = i;\n        }\n    }\n    printf("Topper: %s (Marks: %d)\\n", students[maxIdx].name, students[maxIdx].marks);\n    return 0;\n}\n'}, 94: {'q_id': 144, 'filename': 'day94_q1.c', 'topic': 'Function accepting structure parameter', 'source': '/**\n * Day 94 - Question 144\n * \n * Write a function that accepts a structure as parameter and prints its members.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Student: Neha 104 92\n *   Output: Name: Neha | Roll: 104 | Marks: 92\n *   Explanation: The structure is passed by value to a function that prints its data.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nvoid displayStudent(struct Student s) {\n    printf("Name: %s | Roll: %d | Marks: %d\\n", s.name, s.roll, s.marks);\n}\n\nint main() {\n    struct Student s;\n    if (scanf("%49s %d %d", s.name, &s.roll, &s.marks) == 3) {\n        displayStudent(s);\n    }\n    return 0;\n}\n'}, 95: {'q_id': 145, 'filename': 'day95_q1.c', 'topic': 'Function returning top student structure', 'source': '/**\n * Day 95 - Question 145\n * \n * Return a structure containing top student\'s details from a function.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: 3 students: Riya 101 89, Karan 102 96, Meena 103 92\n *   Output: Top Student: Karan | Roll: 102 | Marks: 96\n *   Explanation: The function returns the structure containing the highest scoring student\'s details.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nstruct Student findTopStudent(struct Student arr[], int n) {\n    int maxIdx = 0;\n    for (int i = 1; i < n; i++) {\n        if (arr[i].marks > arr[maxIdx].marks) {\n            maxIdx = i;\n        }\n    }\n    return arr[maxIdx];\n}\n\nint main() {\n    int n;\n    if (scanf("%d", &n) != 1 || n <= 0) return 0;\n    struct Student students[100];\n    for (int i = 0; i < n; i++) {\n        scanf("%49s %d %d", students[i].name, &students[i].roll, &students[i].marks);\n    }\n    struct Student top = findTopStudent(students, n);\n    printf("Top Student: %s | Roll: %d | Marks: %d\\n", top.name, top.roll, top.marks);\n    return 0;\n}\n'}, 96: {'q_id': 146, 'filename': 'day96_q1.c', 'topic': 'Employee structure with nested Date structure', 'source': '/**\n * Day 96 - Question 146\n * \n * Create Employee structure with nested Date structure for joining date and print details.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Employee: Raj | ID: 11 | Joining Date: 12 05 2020\n *   Output: Name: Raj | ID: 11 | Joining Date: 12/05/2020\n *   Explanation: Nested structure Date is used inside Employee structure to represent joining date.\n */\n\n#include <stdio.h>\n\nstruct Date {\n    int day;\n    int month;\n    int year;\n};\n\nstruct Employee {\n    char name[50];\n    int id;\n    struct Date joiningDate;\n};\n\nint main() {\n    struct Employee emp;\n    if (scanf("%49s %d %d %d %d", emp.name, &emp.id,\n              &emp.joiningDate.day, &emp.joiningDate.month, &emp.joiningDate.year) == 5) {\n        printf("Name: %s | ID: %d | Joining Date: %02d/%02d/%04d\\n",\n               emp.name, emp.id, emp.joiningDate.day, emp.joiningDate.month, emp.joiningDate.year);\n    }\n    return 0;\n}\n'}, 97: {'q_id': 147, 'filename': 'day97_q1.c', 'topic': 'Binary file employee storage using fwrite and fread', 'source': '/**\n * Day 97 - Question 147\n * \n * Store employee data in a binary file using fwrite() and read using fread().\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Employee details entered and stored in file.\n *   Output: Displays employee data read from file.\n *   Explanation: Demonstrates writing and reading structures using binary file handling functions.\n */\n\n#include <stdio.h>\n\nstruct Employee {\n    char name[50];\n    int id;\n    float salary;\n};\n\nint main() {\n    struct Employee empWrite;\n    if (scanf("%49s %d %f", empWrite.name, &empWrite.id, &empWrite.salary) == 3) {\n        FILE *fp = fopen("employee.bin", "wb");\n        if (fp == NULL) return 1;\n        fwrite(&empWrite, sizeof(struct Employee), 1, fp);\n        fclose(fp);\n\n        struct Employee empRead;\n        fp = fopen("employee.bin", "rb");\n        if (fp == NULL) return 1;\n        fread(&empRead, sizeof(struct Employee), 1, fp);\n        fclose(fp);\n\n        printf("Name: %s | ID: %d | Salary: %.2f\\n", empRead.name, empRead.id, empRead.salary);\n    }\n    return 0;\n}\n'}, 98: {'q_id': 148, 'filename': 'day98_q1.c', 'topic': 'Compare two structs for equality', 'source': '/**\n * Day 98 - Question 148\n * \n * Take two structs as input and check if they are identical.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Student1: Asha 101 90\nStudent2: Asha 101 90\n *   Output: Same\n *   Explanation: Compares all structure members and prints \'Same\' if identical.\n */\n\n#include <stdio.h>\n#include <string.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nint areIdentical(struct Student s1, struct Student s2) {\n    return (strcmp(s1.name, s2.name) == 0 && s1.roll == s2.roll && s1.marks == s2.marks);\n}\n\nint main() {\n    struct Student s1, s2;\n    if (scanf("%49s %d %d", s1.name, &s1.roll, &s1.marks) == 3 &&\n        scanf("%49s %d %d", s2.name, &s2.roll, &s2.marks) == 3) {\n        if (areIdentical(s1, s2)) {\n            printf("Same\\n");\n        } else {\n            printf("Not Same\\n");\n        }\n    }\n    return 0;\n}\n'}, 99: {'q_id': 149, 'filename': 'day99_q1.c', 'topic': 'Dynamic structure memory allocation using malloc', 'source': '/**\n * Day 99 - Question 149\n * \n * Use malloc() to allocate structure memory dynamically and print details.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Student allocated dynamically with details: Tina 105 88\n *   Output: Name: Tina | Roll: 105 | Marks: 88\n *   Explanation: Memory for structure is dynamically allocated on heap using malloc().\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nint main() {\n    struct Student *s = (struct Student *)malloc(sizeof(struct Student));\n    if (s == NULL) {\n        printf("Memory allocation failed!\\n");\n        return 1;\n    }\n    if (scanf("%49s %d %d", s->name, &s->roll, &s->marks) == 3) {\n        printf("Name: %s | Roll: %d | Marks: %d\\n", s->name, s->roll, s->marks);\n    }\n    free(s);\n    return 0;\n}\n'}, 100: {'q_id': 150, 'filename': 'day100_q1.c', 'topic': 'Pointer to struct using -> operator', 'source': '/**\n * Day 100 - Question 150\n * \n * Use pointer to struct to modify and display data using -> operator.\n * \n * Test Cases:\n * Test Case 1:\n *   Input: Student pointer modifying values: John 106 91\n *   Output: Modified Data: Name: John | Roll: 106 | Marks: 91\n *   Explanation: Pointer to structure accesses and modifies data using the arrow (->) operator.\n */\n\n#include <stdio.h>\n\nstruct Student {\n    char name[50];\n    int roll;\n    int marks;\n};\n\nvoid modifyStudent(struct Student *ptr, int bonusMarks) {\n    ptr->marks += bonusMarks;\n}\n\nint main() {\n    struct Student s;\n    int bonus;\n    if (scanf("%49s %d %d %d", s.name, &s.roll, &s.marks, &bonus) == 4) {\n        modifyStudent(&s, bonus);\n        printf("Modified Data: Name: %s | Roll: %d | Marks: %d\\n", s.name, s.roll, s.marks);\n    }\n    return 0;\n}\n'}}
